import itertools
import json

types = ["fuel", "grain", "livestock", "machinery", "produce", "textiles"]
options = {"A": 2, "B": 3, "C": 4, "D": 5, "E": 6}

# perm[i] is the cargo type in bay i+1 (bays numbered 1..6)
sols = []
for perm in itertools.permutations(types):
    bay = {perm[i]: i + 1 for i in range(6)}
    if not (bay["grain"] > bay["livestock"] > bay["textiles"]):
        continue
    if not (bay["produce"] > bay["fuel"]):
        continue
    if abs(bay["textiles"] - bay["produce"]) != 1:
        continue
    # exactly one bay between machinery and grain => bay distance of 2
    if abs(bay["machinery"] - bay["grain"]) != 2:
        continue
    sols.append(perm)

per_bay_sets = {}
determined_bays = []
for b in range(6):
    s = sorted({p[b] for p in sols})
    per_bay_sets[str(b + 1)] = s
    if len(s) == 1:
        determined_bays.append(b + 1)

count = len(determined_bays)
matched = [k for k, v in options.items() if v == count]

if not sols or len(matched) != 1:
    final_answer = "UNSUPPORTED"
else:
    final_answer = matched[0]

result = {
    "final_answer": final_answer,
    "evidence": {
        "valid_arrangements": len(sols),
        "determined_bay_count": count,
        "determined_bays": determined_bays,
        "possible_types_per_bay": per_bay_sets,
    },
}
print(json.dumps(result, separators=(",", ":")))
